const today = () => new Date().toISOString().slice(0, 10);

// Posts whose publish date has arrived, newest first
export const publishedPosts = (now = today()) =>
  blogPosts.filter((p) => p.date <= now).sort((a, b) => b.date.localeCompare(a.date));

export const formatPostDate = (date: string) =>
  new Date(`${date}T12:00:00Z`).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
